"""Public English latency report; explicit synthetic receipts, no private data."""
import datetime,hashlib,html,json,statistics
from pathlib import Path

ROOT=Path(__file__).resolve().parent
LIVE=Path('/mnt/nvme/robo-speaker-studies/speaker-live-results')

def main():
    receipts={}
    def read(name,path):
        value=json.loads(path.read_text())
        receipts[name]={'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'data':value}
        return value
    before=read('old_runtime',LIVE/'latency-before.json')
    after=read('current_runtime_unshifted',LIVE/'latency-after.json')
    browser=read('playwright_pause',ROOT/'logs/browser-pause-checks.json')
    comparisons=[]
    for label in ('two-second-comparison','noisy-enrollment-comparison'):
        path=ROOT/'logs'/('browser-pause-'+label+'.json')
        if path.exists():comparisons.append((label,read(label,path)))
    intermediate=read('before_compact_director',ROOT/'logs/browser-pause-before-compact.json')
    context=read('context_lengths',ROOT/'logs/speaker-context-lengths.json')
    impostors=read('background_impostor_probes',ROOT/'logs/background-identity-checks.json')
    anchors=read('anchor_reference_diagnostic',ROOT/'logs/anchor-reference-diagnostic.json')
    reference_lengths=read('enrollment_length_ablation',ROOT/'logs/reference-lengths.json')
    gallery=read('multi_duration_background_probes',ROOT/'logs/background-gallery-checks.json')
    rejected=read('rejected_background_acceptance_revision',ROOT/'logs/failure-before-foreground-guard.json')
    cuda_failure=read('earlier_cuda_failure_sweep',ROOT/'logs/final-verification-cuda-context-failure.json')
    prompts=read('prompt_quality',ROOT/'logs/prompt-quality-checks.json')
    sweep=read('final_sweep',ROOT/'logs/final-verification.json')
    strict=read('earlier_current_strict_sweep',ROOT/'logs/final-verification-current-strict-1792536432.json')
    conversations=[(name,read('final_'+name,LIVE/filename)) for name,filename in
        [('unshifted','three-user-unshifted.json'),('shifted','three-user-live.json')]]
    from final_verify import runtime_signature
    sweep['current_source_matches']=sweep.get('runtime_source_sha256')==runtime_signature()
    sweep['passed']=bool(sweep.get('passed') and sweep['current_source_matches'])
    after_valid=bool(sweep['current_source_matches'] and (LIVE/'latency-after.json').stat().st_mtime>=sweep['started'] and
        any(s['name']=='three_people' and s['passed'] for s in sweep['stages']))
    def timings(value):
        boundaries=[];seen=set()
        for b in value['fixture_boundaries']:
            if 'nonverbal' in b['fixture'] or b['fixture'] in seen:continue
            seen.add(b['fixture']);boundaries.append(b)
        rows=[]
        for i,(boundary,endpoint,audio) in enumerate(zip(boundaries[:6],value['endpoints'][:6],value['first_reply_audio'][:6])):
            rows.append({'turn':i+1,'voice':endpoint['speaker_name'],'fixture':boundary['fixture'],
                'accepted_s':round(endpoint['at_s']-boundary['end_s'],3),'audio_s':round(audio['at_s']-boundary['end_s'],3),
                'prefetch_used':endpoint.get('timing',{}).get('prefetch_used')})
        return rows
    old,new=timings(before),timings(after)
    e=lambda value:html.escape(str(value))
    def table(headers,rows):return '<div class="scroll"><table><tr>'+''.join('<th>'+e(h)+'</th>' for h in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</table></div>'
    def median(rows,key):return statistics.median(r[key] for r in rows)
    out='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby: one-second pauses and faster replies</title><style>body{font:17px/1.6 system-ui;max-width:1100px;margin:auto;padding:28px;background:#f7f8fb;color:#192333}table{border-collapse:collapse;background:white;width:100%}td,th{padding:9px;border:1px solid #dce1e8;text-align:left}.scroll{overflow:auto}pre{white-space:pre-wrap;font-size:12px}h1,h2{line-height:1.2}.note{padding:16px;background:#fff0ce}</style><a href="/desk-robot/">Open 3D Robby</a> · <a href="/static/report.html">Full integration report</a><h1>One-second speaker pauses and faster answers</h1>'''
    out+='<p>Generated '+e(datetime.datetime.now(datetime.timezone.utc).isoformat())+'. Same configured Luna provider/model, same shared Humaneness Small RL GPU model, RTX 3090 host. All audio fixtures are public synthetic voices; no physical microphone was available.</p>'
    if not sweep['passed']:out+='<p class="note">The final regression sweep has not passed all checks on the current source. Read the individual failed stages below; this is not a claim of completed reliability validation.</p>'
    if not after_valid:out+='<p class="note">The before/after table uses an earlier completed unshifted replay, not a current-source completed conversation. It must not be treated as verified performance of the final revision.</p>'
    out+=table(['Measurement','Before','After','Scope'],[
        ['Recognized returning speaker → submitted (median)',f'{median(old[3:],"accepted_s"):.3f} s',f'{median(new[3:],"accepted_s"):.3f} s','Three returning-user questions; introduction grace excluded'],
        ['Recognized returning speaker → first audio (median)',f'{median(old[3:],"audio_s"):.3f} s',f'{median(new[3:],"audio_s"):.3f} s','Includes Luna/shared TTS'],
        ['Returning-user submission range',str((min(r['accepted_s'] for r in old[3:]),max(r['accepted_s'] for r in old[3:]))),str((min(r['accepted_s'] for r in new[3:]),max(r['accepted_s'] for r in new[3:]))),'All delays, including explicit repeats; inspect individual turns'],
        ['Returning-user first-audio range',str((min(r['audio_s'] for r in old[3:]),max(r['audio_s'] for r in old[3:]))),str((min(r['audio_s'] for r in new[3:]),max(r['audio_s'] for r in new[3:]))),'A median alone hides difficult turns'],
        ['Accepted turn after speech (median)',f'{median(old,"accepted_s"):.3f} s',f'{median(new,"accepted_s"):.3f} s','Six turns; three introductions + three returning users'],
        ['First streamed audio after speech (median)',f'{median(old,"audio_s"):.3f} s',f'{median(new,"audio_s"):.3f} s','Includes Luna + shared TTS; not just the endpoint timer'],
        ['All-six submission mean',round(statistics.mean(r['accepted_s'] for r in old),3),round(statistics.mean(r['accepted_s'] for r in new),3),'Includes full retry delays; not a typical-case-only statistic'],
        ['All-six first-audio mean',round(statistics.mean(r['audio_s'] for r in old),3),round(statistics.mean(r['audio_s'] for r in new),3),'Retries can worsen the mean despite an improved median'],
        ['Explicit repeats',len(before.get('explicit_repeats',[])),len(after.get('explicit_repeats',[])),'No hidden retry/recovery removed from measurements'],
        ['Default identity context','2 s','3.04 s','Uses already-heard speech, never waits to fill a window'],
        ['Current frozen-source QA','—',sweep.get('passed'),'Runtime hash and individual stages below']])
    out+='<h2>What changed</h2><p>The one-second clock belongs to the recognized speaker, not the entire room. Silence from that speaker is not prolonged by a background voice or a stale diarization channel. Read-only ASR/voice verification starts during the pause (240-ms configured threshold), but no answer is requested before the deadline. Resumed speech invalidates the prepared result. Final turns take priority over queued background previews.</p><p>A single compact Luna call produces one answer, acting SCRIPT and language. The existing TTS manual endpoint then speaks that literal prompt without another director call. Redundant answer fields and a serial name-resolution API call were removed. Acoustic enrollment remains authoritative. Ordinary answers are concise and concrete; requested constraints, verbatim wording and follow-ups take priority. No tools or device actions are fabricated.</p>'
    out+='<h2>Matched three-user conversation</h2><p>Sequential real-time loopback audio with ongoing unrelated speech, same fixtures/noise phase; dynamic answer lengths and shared-service/API jitter are not controlled. This is an observed engineering comparison, not a randomized causal study. Introductions retain a separate wake/name grace; returning speakers use the normal one-second clock.</p>'
    out+='<p class="note">The background has the same initial phase, not necessarily the same phase at each later utterance: variable reply durations shift subsequent requests. The noisy multi-user replay required repeats and its mean latency worsened; this revision must not be advertised as universally faster or perfectly reliable. The fixed-timeline browser cases separately validate the one-second recognized-speaker pause behavior. Real-room speaker calibration remains necessary.</p>'
    out+='<p>The final boundary path uses already-arrived native 320-ms timestamps as positive continuity for an existing known speaker, guarded by a separated fast winner, foreground level and at most 1.6 s since direct diarizer evidence. Delayed diarizer rows cannot rewind that timestamp. It creates neither a new identity nor an interruption. The fast enrollment anchor is now a time-aligned mean of native observations inside the verified introduction, excluding quiet pre-roll, rather than a mean of repeatedly sampled reused-channel subframes. Sparse but genuinely loud candidate audio can trigger independent full known-reference verification even when masked ASR lost its words; this does not enable unknown-user enrollment.</p>'
    out+='<p>A close known-person teacher winner can be corroborated only by the same independent fast winner (teacher >=max(0.55, configured threshold), teacher margin >=max(0.04, configured margin/2), fast cosine >=max(0.60, fast threshold), fast margin >=0.10). For interruptions, actual DAC-aligned playback content is also checked: a known speaker passing the normal 0.50 floor and 0.12 other-user margin may satisfy a native BARGE proposal when absolute waveform correlation to active playback is below 0.12 across +/-450 ms. Similar voice timbre alone is not an echo. Actual/delayed/inverted echo waveforms retain their veto; no interruption is created without the original native proposal. Room/reverb robustness remains unmeasured.</p>'
    out+='<p class="note">A rejected development revision accepted unrelated background-TV speech after a similar-timbre match. Its failed replay is preserved below, not counted as success. The current default adds a foreground floor at twice the measured median amplitude of observed background channels: a quieter match cannot renew/reassign a user clock or trigger an interruption. This is not source separation and can reject genuinely quiet low-SNR speech. Clean-reference impostor probes below do not measure the error rate of arbitrary online enrollments.</p>'
    out+='<p>A separate CUDA-context failure also interrupted a test sweep. Its cause was not established as a hardware fault. Native ticks, feature taps and transcription now share a reentrant GPU scheduling guard; no model math or weights changed. A dead/fatal audio worker reports not ready rather than silently appearing microphone-ready. Recovery still requires restarting the owned worker; no shared-GPU reset or termination of unrelated jobs was used.</p>'
    out+=table(['Voice/turn','Old submit','New submit','Old first audio','New first audio','Prepared result'],[[f'{a["voice"]} / {a["turn"]}',b['accepted_s'],a['accepted_s'],b['audio_s'],a['audio_s'],a['prefetch_used']] for b,a in zip(old,new)])
    out+='<h2>Actual HTTPS Playwright capture</h2><p>Chrome fake getUserMedia → actual capture worklet → WebSocket → Nemotron ASR/diarization → enrolled voice gate → Luna → streamed TTS. The background keeps talking. The foreground question contains an 800-ms hesitation: it must not be submitted mid-sentence. Captured PCM is cross-correlated against the source to align the speech-ending clock. Exactly two correct-ID accepted turns and actual audio replies are required; background duplicates and page/runtime errors fail the check.</p>'
    out+=table(['Identity context','Passed','Pause → submitted','Pause → first audio','Question WER','Prefetch'],[[r['mode'],r['passed'],r.get('pause_to_accepted_turn_s'),r.get('pause_to_first_audio_s'),r.get('question_wer'),(r.get('endpoint_metrics') or {}).get('prefetch_used')] for r in browser['cases']])
    out+=table(['Case','Accepted question','Actual reply'],[[i+1,r['endpoints'][1]['transcript'] if len(r.get('endpoints',[]))>1 else 'not accepted',r.get('replies',[])[-1] if r.get('replies') else 'none'] for i,r in enumerate(browser['cases'])])
    if any(r.get('question_wer',0)>0 for r in browser['cases']):out+='<p class="note">A nonzero WER remains visible above: passing this check allows up to 0.25 WER, not perfect transcription. In exploratory passing runs a trailing background word (for example “Morgen”) sometimes remained. No separate background turn was accepted in those passing cases. This is not a claim of complete background-word removal.</p>'
    out+='<p>The targeted default-session test enrolls the speaker in clean audio first, then starts continuous background speech before the later question. It tests an already-recognized speaker, not noisy initial enrollment. The multi-user sweep separately retains noisy introductions. An earlier all-noisy version exposed split-channel enrollment failures and background-word contamination; those exploratory failures are not counted as successful latency measurements.</p>'
    if comparisons:
        out+='<h3>Explicit separate comparison conditions</h3>'+table(['Condition','Overall passed','Context','Case passed','Submit latency','Question WER'],[[label,value['passed'],r['mode'],r['passed'],r.get('pause_to_accepted_turn_s'),r.get('question_wer')] for label,value in comparisons for r in value['cases']])
    out+='<p>Intermediate pause-only optimization, before compact directing: '+e([(r['mode'],r.get('pause_to_first_audio_s')) for r in intermediate['cases']])+'. These are separate runs, not additional independent speakers.</p>'
    cold=ROOT/'logs/browser-pause-compact-cold-failure.json'
    if cold.exists():
        read('exploratory_browser_failure',cold)
        out+='<p class="note">Exploratory testing also encountered a cold-start browser run with no accepted turns. Its failed receipt is preserved rather than counted as success. See the final tests below for the current verification outcome; passing repeated synthetic cases does not establish perfect real-room reliability.</p>'
    prefix=ROOT/'logs/browser-pause-prefix-failure.json'
    if prefix.exists():read('exploratory_prefix_failure',prefix)
    out+='<p>Development findings: releasing every channel, a short CPU-teacher activity veto and amplitude-only onset cropping lost soft openings or returning words; these variants were rejected. A last-three-seconds-only final check hid TV prefixes and was removed. Stale ASR jobs could leave a channel permanently marked decoding; a finally block now clears it. A provisional Guest wake flag could incorrectly carry into a later background turn; named users now require fresh activation evidence.</p><p>Current continuity uses already-available 320-ms fast cues: a clearly incompatible current voice (centered similarity below 0.15) cannot renew a known channel, while compatible audible words can recover short-classifier silence misses. These permissive clock cues do not enroll or finally verify identity. Full-span independent verification defaults to cosine 0.45 / nearest-user margin 0.08 (historical baseline: 0.50 / 0.08); interruption verification retains a stricter 0.50 floor. These are engineering prototype settings, not calibrated identity probabilities.</p><p>A two-second protective look-behind preserves soft opening words. A bounded pre-roll crop is allowed only if the removed prefix independently fails all known voice references (cosine below 0.35 at the default threshold), its 95th-percentile RMS is no more than 0.6 of retained-speech 75th-percentile RMS, and the retained full view passes the configured voice threshold/margin and owned-word ASR. The original whole-span embedding remains a 20% independent verification view. This removes proven quiet other-voice prefixes rather than choosing an arbitrarily shorter transcript to increase cosine. It is not source separation. Preparation starts at the first quiet hop (240-ms configured threshold); no LLM request is sent before the one-second deadline.</p>'
    out+='<h2>Longer voice windows</h2><p>Frozen CPU ECAPA teacher, three synthetic voices, three background gains and two phases: 18 correlated cases per window. Fixed cosine ≥0.50 and nearest-speaker margin ≥0.08, not tuned per condition. All top-1 identities were correct, but confidence gates abstained frequently with short audio. The up-to-six-second condition uses only available speech (roughly 2.35–4.99 s), no padding or extra waiting.</p>'
    out+=table(['Maximum context','Cases','Correct accepted','Wrong accepted','Abstained'],[[r['max_context_s'],r['cases'],r['correct_accepted'],r['wrong_accepted'],r['abstentions']] for r in context['results']])
    out+='<p>3.04 seconds is the current practical choice, not “longer is always better.” This small teacher experiment does not measure student generalization. The previous speaker-disjoint V5 comparison found only +0.43 percentage points for 3.04 versus 2 seconds (interval crosses zero). Fast ownership cues still run every 320 ms.</p>'
    out+='<h3>Why the actual reference boundary matters</h3><p>One failed public-synthetic introduction replay exposed a contaminated voice anchor. An activity-derived last-speech timestamp cut off useful word endings while retaining earlier quiet background speech. The new reference keeps already-captured endings, uses a same-name introduction view, then selects the highest-energy contiguous window of up to 3.04 s. It changes the enrollment embedding only, never the spoken transcript, original TYGER weights or the TTS model’s reference-audio limit. A new registration retains 2.5 s of quiet grace until its reference is ready; recognized subsequent turns use one second. This is one diagnostic, not an accuracy benchmark.</p>'
    out+=table(['Reference construction','Duration','Cosine to clean Robert','Cosine to unrelated background'],[[r['condition'],r['reference_seconds'],r['cosines']['intended Robert'],r['cosines']['unrelated background']] for r in anchors['rows']])
    out+='<p>The duration experiment above uses fixed trailing contexts; it is not a direct benchmark of this new energy-selected enrollment recipe. The new final live default remains cosine 0.50 / nearest-user margin 0.08. An exploratory 0.45 threshold was not retained. Correlated views and a small repeated synthetic set do not establish real-person accuracy.</p>'
    out+='<h3>A single enrollment crop was not robust</h3><p>A separate duration ablation found strong phonetic dependence: the three-second introduction crop was worse for Christoph than two/four seconds, while Selma favored three seconds. The live system now keeps up to three energy-selected templates (2, 3.04 and 4 s) from the same verified introduction. Known-voice scoring takes the maximum per person, with margins against other identities, not against another template of the same person. These are bounded RAM-only templates; no test label, downstream query or target cosine chooses the reference windows. Matching multiple templates changes score calibration and is not a biometric guarantee.</p>'
    out+=table(['Speaker','Maximum reference length','Actual length','Noise gain','Same-voice cosine','Background cosine'],[[r['speaker'],r['max_reference_s'],r['actual_reference_s'],r['background_gain'],r['same_voice_cosine'],r['background_cosine']] for r in reference_lengths['rows']])
    out+='<p>Multi-template background check: '+e(len(gallery['rows']))+' correlated probes, maximum impostor cosine '+e(max(r['highest'] for r in gallery['rows']))+', '+e(sum(r['accepted_at_full_threshold'] for r in gallery['rows']))+' crossed the default 0.50 gate. Only one unrelated synthetic background identity was tested; this cannot estimate a real-room false-acceptance rate.</p>'
    out+='<p>The multi-template prefix exclusion gate is below min(0.45, normal threshold minus 0.05), plus the quiet-energy and full retained-speaker checks. Ordinary raw/cropped views must agree at 0.50; a proven quiet other-voice prefix alone permits 0.35 agreement, retaining the original view at 20% weight. The complete retained transcript may not worsen owned-word edit agreement relative to the best ASR view. This fixed an exploratory failure where an acoustic prefix-repair candidate incorrectly replaced a clean question with a TV-prefixed question. These are explicit prototype operating points, not calibrated guarantees.</p>'
    out+='<p>Additional background-impostor check: ten correlated duration/phase probes against the three clean references; maximum cosine '+e(max(r['highest'] for r in impostors['rows']))+'. None crossed even the exploratory 0.45 threshold (the retained default is 0.50). This is one synthetic background identity and is not a real-world false-acceptance-rate estimate.</p>'
    out+='<h2>Instruction-following regression checks</h2><p>Seven actual compact-Luna calls, explicit inspectable predicates. This is not a general intelligence benchmark; outputs are shown for human review.</p>'
    out+=table(['Case','Request','Actual answer','Passed','Director ms'],[[r['name'],r['request'],r['reply'],r['passed'],r['director_ms']] for r in prompts['cases']])
    out+='<h2>Final regression sweep</h2>'+table(['Stage','Passed','Seconds'],[[s['name'],s['passed'],round(s.get('seconds',0),2)] for s in sweep['stages']])
    out+='<p class="note">An earlier strict revision passed all six unshifted requests and a real interruption, then failed initial Robert enrollment under the 2.3-second-shifted background. That failure is retained, not removed from the study. A later interruption check missed a quiet user onset; the current version uses up to 3.04 s of already-captured interruption evidence rather than 1.92 s. The final sweep permits at most '+e(sweep.get('max_explicit_repeats_per_turn',0))+' explicit repetition per utterance after nine seconds without acceptance. This is a bounded conversational-recovery test, not perfect first-pass recognition. The matched before/after latency table uses the final unshifted replay, including the full delay of any explicit repeats.</p>'
    out+=table(['Final condition','Named requests','Explicit repetitions','All first attempts accepted'],[[label,len(value.get('replies',[])),len(value.get('explicit_repeats',[])),value.get('all_first_attempts_accepted')] for label,value in conversations])
    out+='<p>Explicit repeat details: '+e([(label,value.get('explicit_repeats',[])) for label,value in conversations])+'. All scenarios reuse development identities/fixtures and are not held-out real-person validation.</p>'
    out+='<h2>Limits and reproduction</h2><p class="note">Diarization is not source separation. Loud overlapping people, distant microphones, unseen real voices and very short utterances can still require repetition. Speaker embeddings are approximate identity cues, not authentication. One live slot is shared; model/API queues affect first-audio latency. Physical room/device latency was not tested. Session microphone audio and enrolled voiceprints are not published.</p><p>Source: <a href="/downloads/robby-source.zip">audited source ZIP</a>. Run <code>python final_verify.py</code>, <code>python prompt_quality_checks.py</code>, and <code>python -m speaker_live.context_lengths</code> with the documented model/configuration paths. The full prompts are in conversation_prompt.py and conversation_director.py. The changes follow the <a href="https://developers.openai.com/api/docs/guides/latency-optimization">official latency guidance</a> (reduce serial calls/output) and <a href="https://developers.openai.com/api/docs/guides/prompt-engineering">prompting guidance</a> (explicit task, context and format).</p>'
    out+='<details><summary>Auditable synthetic receipts, metrics and hashes</summary><pre>'+e(json.dumps(receipts,indent=2,ensure_ascii=False))+'</pre></details></html>'
    out=out.replace('Full-span independent verification defaults to cosine 0.45 / nearest-user margin 0.08 (historical baseline: 0.50 / 0.08); interruption verification retains a stricter 0.50 floor.',
        'Full-span independent verification retains cosine 0.50 / nearest-user margin 0.08; interruption verification also retains a minimum 0.50 floor even if normal-turn strictness is lowered in the UI.')
    out=out.replace('cosine below 0.35 at the default threshold','cosine below 0.45 at the default threshold')
    target=ROOT/'static/turn-latency.html';target.write_text(out)
    print(json.dumps({'report':str(target),'before_endpoint_median':median(old,'accepted_s'),'after_endpoint_median':median(new,'accepted_s'),'before_audio_median':median(old,'audio_s'),'after_audio_median':median(new,'audio_s'),'browser_passed':browser['passed'],'final_passed':sweep['passed']}))

if __name__=='__main__':main()
